// Data Storage
let appData = {
    tasks: [],
    grades: [],
    mentalHealth: [],
    initialized: false
};

// Load data from localStorage
function loadData() {
    const stored = localStorage.getItem('swmsData');
    if (stored) {
        appData = JSON.parse(stored);
    }
    if (!appData.initialized) {
        initializeSampleData();
    }
}

// Save data to localStorage
function saveData() {
    localStorage.setItem('swmsData', JSON.stringify(appData));
}

// Initialize with sample data
function initializeSampleData() {
    const today = new Date();
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);
    const nextWeek = new Date(today);
    nextWeek.setDate(nextWeek.getDate() + 7);

    appData.tasks = [
        {
            id: Date.now(),
            title: 'Complete Data Structures Assignment',
            description: 'Implement binary search tree',
            dueDate: tomorrow.toISOString().split('T')[0],
            priority: 'high',
            completed: false
        },
        {
            id: Date.now() + 1,
            title: 'Study for Calculus Midterm',
            description: 'Review chapters 5-8',
            dueDate: nextWeek.toISOString().split('T')[0],
            priority: 'high',
            completed: false
        },
        {
            id: Date.now() + 2,
            title: 'Read Psychology Chapter 3',
            description: 'Cognitive development theories',
            dueDate: nextWeek.toISOString().split('T')[0],
            priority: 'medium',
            completed: false
        }
    ];

    appData.grades = [
        { id: Date.now(), course: 'Data Structures', grade: 3.7, credits: 4, date: '2026-09-01' },
        { id: Date.now() + 1, course: 'Calculus II', grade: 3.5, credits: 4, date: '2026-09-05' },
        { id: Date.now() + 2, course: 'Psychology', grade: 3.9, credits: 3, date: '2026-09-10' },
        { id: Date.now() + 3, course: 'English Literature', grade: 3.8, credits: 3, date: '2026-09-12' }
    ];

    appData.mentalHealth = [
        { date: '2026-09-12', stress: 6, anxiety: 5, mood: 3, sleep: 6.5 },
        { date: '2026-09-13', stress: 7, anxiety: 6, mood: 3, sleep: 6 },
        { date: '2026-09-14', stress: 5, anxiety: 4, mood: 4, sleep: 7.5 },
        { date: '2026-09-15', stress: 8, anxiety: 7, mood: 2, sleep: 5.5 },
        { date: '2026-09-16', stress: 6, anxiety: 5, mood: 3, sleep: 7 },
        { date: '2026-09-17', stress: 4, anxiety: 3, mood: 4, sleep: 8 },
        { date: '2026-09-18', stress: 5, anxiety: 4, mood: 4, sleep: 7.5 }
    ];

    appData.initialized = true;
    saveData();
}

// Navigation
document.querySelectorAll('.nav-item').forEach(item => {
    item.addEventListener('click', function() {
        const view = this.dataset.view;
        switchView(view);

        document.querySelectorAll('.nav-item').forEach(nav => nav.classList.remove('active'));
        this.classList.add('active');
    });
});

function switchView(viewName) {
    document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
    document.getElementById(`${viewName}-view`).classList.add('active');

    // Update view-specific content
    if (viewName === 'dashboard') updateDashboard();
    if (viewName === 'performance') updatePerformance();
    if (viewName === 'mental-health') updateMentalHealth();
    if (viewName === 'tasks') updateTasks();
}

// Dashboard Functions
function updateDashboard() {
    // Update date
    const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    document.getElementById('current-date').textContent = new Date().toLocaleDateString('en-US', options);

    // Update stats
    const pendingTasks = appData.tasks.filter(t => !t.completed).length;
    document.getElementById('pending-tasks').textContent = pendingTasks;

    const gpa = calculateGPA();
    document.getElementById('current-gpa').textContent = gpa.toFixed(2);

    const completionRate = calculateCompletionRate();
    document.getElementById('completion-rate').textContent = completionRate + '%';

    const stressLevel = getLatestStressLevel();
    document.getElementById('stress-level').textContent = stressLevel.label;
    const stressCard = document.querySelector('.stress-card');
    stressCard.classList.remove('low', 'medium', 'high');
    stressCard.classList.add(stressLevel.class);

    // Update upcoming deadlines
    updateUpcomingDeadlines();

    // Update workload chart
    createWorkloadChart();
}

function calculateGPA() {
    if (appData.grades.length === 0) return 0;
    const totalPoints = appData.grades.reduce((sum, g) => sum + (g.grade * g.credits), 0);
    const totalCredits = appData.grades.reduce((sum, g) => sum + g.credits, 0);
    return totalCredits > 0 ? totalPoints / totalCredits : 0;
}

function calculateCompletionRate() {
    if (appData.tasks.length === 0) return 0;
    const completed = appData.tasks.filter(t => t.completed).length;
    return Math.round((completed / appData.tasks.length) * 100);
}

function getLatestStressLevel() {
    if (appData.mentalHealth.length === 0) return { label: 'Unknown', class: 'low' };
    const latest = appData.mentalHealth[appData.mentalHealth.length - 1];
    const stress = latest.stress;

    if (stress <= 3) return { label: 'Low', class: 'low' };
    if (stress <= 6) return { label: 'Medium', class: 'medium' };
    return { label: 'High', class: 'high' };
}

function updateUpcomingDeadlines() {
    const container = document.getElementById('deadlines-list');
    const upcomingTasks = appData.tasks
        .filter(t => !t.completed)
        .sort((a, b) => new Date(a.dueDate) - new Date(b.dueDate))
        .slice(0, 5);

    if (upcomingTasks.length === 0) {
        container.innerHTML = '<p class="empty-state">No upcoming deadlines</p>';
        return;
    }

    container.innerHTML = upcomingTasks.map(task => {
        const daysUntil = getDaysUntilDue(task.dueDate);
        return `
            <div class="deadline-item ${task.priority}">
                <h4>${task.title}</h4>
                <p>📅 ${formatDate(task.dueDate)} (${daysUntil})</p>
            </div>
        `;
    }).join('');
}

function getDaysUntilDue(dueDate) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const due = new Date(dueDate);
    due.setHours(0, 0, 0, 0);
    const diff = Math.ceil((due - today) / (1000 * 60 * 60 * 24));

    if (diff < 0) return 'Overdue';
    if (diff === 0) return 'Due today';
    if (diff === 1) return 'Due tomorrow';
    return `${diff} days left`;
}

function formatDate(dateString) {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}

// Chart Functions
function createWorkloadChart() {
    const ctx = document.getElementById('workloadChart');
    if (!ctx) return;

    // Clear existing chart
    if (window.workloadChartInstance) {
        window.workloadChartInstance.destroy();
    }

    const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
    const data = [5, 7, 6, 8, 9, 4, 3]; // Sample workload hours

    // Simple bar chart using canvas
    const canvas = ctx;
    canvas.width = canvas.offsetWidth;
    canvas.height = 250;
    const context = canvas.getContext('2d');

    const barWidth = canvas.width / days.length;
    const maxHeight = canvas.height - 40;
    const maxValue = Math.max(...data);

    context.clearRect(0, 0, canvas.width, canvas.height);

    data.forEach((value, index) => {
        const barHeight = (value / maxValue) * maxHeight;
        const x = index * barWidth + 10;
        const y = canvas.height - barHeight - 20;

        // Draw bar
        context.fillStyle = '#6366f1';
        context.fillRect(x, y, barWidth - 20, barHeight);

        // Draw label
        context.fillStyle = '#cbd5e1';
        context.font = '12px sans-serif';
        context.textAlign = 'center';
        context.fillText(days[index], x + (barWidth - 20) / 2, canvas.height - 5);

        // Draw value
        context.fillText(value + 'h', x + (barWidth - 20) / 2, y - 5);
    });
}

// Performance Functions
function updatePerformance() {
    const gpa = calculateGPA();
    document.getElementById('perf-gpa').textContent = gpa.toFixed(2);

    updateGradesList();
    updateCompletionCircle();
    createGPAChart();
}

function updateGradesList() {
    const container = document.getElementById('grades-list');

    if (appData.grades.length === 0) {
        container.innerHTML = '<p class="empty-state">No grades recorded yet</p>';
        return;
    }

    const sortedGrades = [...appData.grades].sort((a, b) => new Date(b.date) - new Date(a.date));

    container.innerHTML = sortedGrades.map(grade => `
        <div class="grade-item">
            <div class="grade-info">
                <h4>${grade.course}</h4>
                <p>${grade.credits} credits • ${formatDate(grade.date)}</p>
            </div>
            <div class="grade-value">${grade.grade.toFixed(1)}</div>
        </div>
    `).join('');
}

function updateCompletionCircle() {
    const rate = calculateCompletionRate();
    const circle = document.getElementById('completion-circle');
    const percentage = document.getElementById('completion-percentage');
    const completed = appData.tasks.filter(t => t.completed).length;
    const total = appData.tasks.length;

    circle.style.strokeDasharray = `${rate}, 100`;
    percentage.textContent = `${rate}%`;
    document.getElementById('completed-count').textContent = completed;
    document.getElementById('total-count').textContent = total;
}

function createGPAChart() {
    const ctx = document.getElementById('gpaChart');
    if (!ctx) return;

    if (window.gpaChartInstance) {
        window.gpaChartInstance.destroy();
    }

    const canvas = ctx;
    canvas.width = canvas.offsetWidth;
    canvas.height = 250;
    const context = canvas.getContext('2d');

    // Calculate semester GPAs (simplified)
    const semesters = ['Fall 25', 'Spring 26', 'Summer 26', 'Fall 26'];
    const gpas = [3.5, 3.6, 3.7, calculateGPA()];

    const padding = 40;
    const width = canvas.width - padding * 2;
    const height = canvas.height - padding * 2;
    const pointSpacing = width / (gpas.length - 1);

    context.clearRect(0, 0, canvas.width, canvas.height);

    // Draw grid lines
    context.strokeStyle = '#475569';
    context.lineWidth = 1;
    for (let i = 0; i <= 4; i++) {
        const y = padding + (height / 4) * i;
        context.beginPath();
        context.moveTo(padding, y);
        context.lineTo(canvas.width - padding, y);
        context.stroke();

        // Draw y-axis labels
        context.fillStyle = '#94a3b8';
        context.font = '12px sans-serif';
        context.textAlign = 'right';
        context.fillText((4 - i).toFixed(1), padding - 10, y + 4);
    }

    // Draw line
    context.strokeStyle = '#6366f1';
    context.lineWidth = 3;
    context.beginPath();

    gpas.forEach((gpa, index) => {
        const x = padding + index * pointSpacing;
        const y = padding + height - (gpa / 4) * height;

        if (index === 0) {
            context.moveTo(x, y);
        } else {
            context.lineTo(x, y);
        }

        // Draw point
        context.fillStyle = '#6366f1';
        context.beginPath();
        context.arc(x, y, 5, 0, Math.PI * 2);
        context.fill();

        // Draw x-axis label
        context.fillStyle = '#cbd5e1';
        context.font = '12px sans-serif';
        context.textAlign = 'center';
        context.fillText(semesters[index], x, canvas.height - 10);
    });

    context.stroke();
}

// Mental Health Functions
function updateMentalHealth() {
    createStressChart();
    updateMoodHistory();
}

function createStressChart() {
    const ctx = document.getElementById('stressChart');
    if (!ctx) return;

    if (window.stressChartInstance) {
        window.stressChartInstance.destroy();
    }

    const canvas = ctx;
    canvas.width = canvas.offsetWidth;
    canvas.height = 250;
    const context = canvas.getContext('2d');

    const last7Days = appData.mentalHealth.slice(-7);
    const labels = last7Days.map(d => {
        const date = new Date(d.date);
        return date.toLocaleDateString('en-US', { weekday: 'short' });
    });
    const stressData = last7Days.map(d => d.stress);

    const padding = 40;
    const width = canvas.width - padding * 2;
    const height = canvas.height - padding * 2;
    const pointSpacing = width / (stressData.length - 1);

    context.clearRect(0, 0, canvas.width, canvas.height);

    // Draw grid
    context.strokeStyle = '#475569';
    context.lineWidth = 1;
    for (let i = 0; i <= 10; i += 2) {
        const y = padding + (height / 10) * i;
        context.beginPath();
        context.moveTo(padding, y);
        context.lineTo(canvas.width - padding, y);
        context.stroke();

        context.fillStyle = '#94a3b8';
        context.font = '12px sans-serif';
        context.textAlign = 'right';
        context.fillText((10 - i).toString(), padding - 10, y + 4);
    }

    // Draw line with gradient
    const gradient = context.createLinearGradient(0, padding, 0, canvas.height - padding);
    gradient.addColorStop(0, '#ef4444');
    gradient.addColorStop(0.5, '#f59e0b');
    gradient.addColorStop(1, '#10b981');

    context.strokeStyle = gradient;
    context.lineWidth = 3;
    context.beginPath();

    stressData.forEach((stress, index) => {
        const x = padding + index * pointSpacing;
        const y = padding + height - (stress / 10) * height;

        if (index === 0) {
            context.moveTo(x, y);
        } else {
            context.lineTo(x, y);
        }

        // Draw point
        context.fillStyle = '#6366f1';
        context.beginPath();
        context.arc(x, y, 5, 0, Math.PI * 2);
        context.fill();

        // Draw label
        context.fillStyle = '#cbd5e1';
        context.font = '12px sans-serif';
        context.textAlign = 'center';
        context.fillText(labels[index], x, canvas.height - 10);
    });

    context.stroke();
}

function updateMoodHistory() {
    const container = document.getElementById('mood-history-list');

    if (appData.mentalHealth.length === 0) {
        container.innerHTML = '<p class="empty-state">No mood records yet</p>';
        return;
    }

    const moodEmojis = ['😢', '😟', '😐', '🙂', '😄'];
    const recent = [...appData.mentalHealth].reverse().slice(0, 10);

    container.innerHTML = recent.map(record => `
        <div class="mood-history-item">
            <div class="mood-emoji">${moodEmojis[record.mood - 1]}</div>
            <div class="mood-details">
                <p><strong>${formatDate(record.date)}</strong></p>
                <p>Stress: ${record.stress}/10 • Anxiety: ${record.anxiety}/10 • Sleep: ${record.sleep}h</p>
            </div>
        </div>
    `).join('');
}

// Mental Health Form
const stressSlider = document.getElementById('stress-slider');
const anxietySlider = document.getElementById('anxiety-slider');
const stressValue = document.getElementById('stress-value');
const anxietyValue = document.getElementById('anxiety-value');

if (stressSlider) {
    stressSlider.addEventListener('input', function() {
        stressValue.textContent = this.value;
    });
}

if (anxietySlider) {
    anxietySlider.addEventListener('input', function() {
        anxietyValue.textContent = this.value;
    });
}

// Mood selector
let selectedMood = 3;
document.querySelectorAll('.mood-btn').forEach(btn => {
    btn.addEventListener('click', function() {
        document.querySelectorAll('.mood-btn').forEach(b => b.classList.remove('selected'));
        this.classList.add('selected');
        selectedMood = parseInt(this.dataset.mood);
    });
});

// Assessment form submission
const assessmentForm = document.getElementById('assessment-form');
if (assessmentForm) {
    assessmentForm.addEventListener('submit', function(e) {
        e.preventDefault();

        const assessment = {
            date: new Date().toISOString().split('T')[0],
            stress: parseInt(stressSlider.value),
            anxiety: parseInt(anxietySlider.value),
            mood: selectedMood,
            sleep: parseFloat(document.getElementById('sleep-hours').value)
        };

        // Remove today's entry if exists
        appData.mentalHealth = appData.mentalHealth.filter(m => m.date !== assessment.date);
        appData.mentalHealth.push(assessment);

        saveData();
        updateMentalHealth();
        updateDashboard();

        showNotification('Assessment saved successfully!');
    });
}

// Tasks Functions
function updateTasks(filter = 'all') {
    const container = document.getElementById('tasks-list');
    let tasksToShow = appData.tasks;

    if (filter === 'pending') {
        tasksToShow = appData.tasks.filter(t => !t.completed);
    } else if (filter === 'completed') {
        tasksToShow = appData.tasks.filter(t => t.completed);
    }

    if (tasksToShow.length === 0) {
        container.innerHTML = '<p class="empty-state">No tasks found</p>';
        return;
    }

    // Sort by due date
    tasksToShow.sort((a, b) => new Date(a.dueDate) - new Date(b.dueDate));

    container.innerHTML = tasksToShow.map(task => {
        const daysUntil = getDaysUntilDue(task.dueDate);
        return `
            <div class="task-item ${task.priority} ${task.completed ? 'completed' : ''}" data-task-id="${task.id}">
                <div class="task-checkbox ${task.completed ? 'checked' : ''}" onclick="toggleTask(${task.id})"></div>
                <div class="task-content">
                    <h4>${task.title}</h4>
                    ${task.description ? `<p>${task.description}</p>` : ''}
                    <div class="task-meta">
                        <span>📅 ${formatDate(task.dueDate)}</span>
                        <span>${daysUntil}</span>
                        <span class="priority-badge">${task.priority.toUpperCase()}</span>
                    </div>
                </div>
                <div class="task-actions">
                    <button class="icon-btn" onclick="deleteTask(${task.id})" title="Delete">🗑️</button>
                </div>
            </div>
        `;
    }).join('');
}

function toggleTask(taskId) {
    const task = appData.tasks.find(t => t.id === taskId);
    if (task) {
        task.completed = !task.completed;
        saveData();
        updateTasks();
        updateDashboard();
    }
}

function deleteTask(taskId) {
    if (confirm('Are you sure you want to delete this task?')) {
        appData.tasks = appData.tasks.filter(t => t.id !== taskId);
        saveData();
        updateTasks();
        updateDashboard();
        showNotification('Task deleted');
    }
}

// Task filters
document.querySelectorAll('.filter-btn').forEach(btn => {
    btn.addEventListener('click', function() {
        document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
        this.classList.add('active');
        updateTasks(this.dataset.filter);
    });
});

// Modal Functions
function openModal(modalId) {
    document.getElementById(modalId).classList.add('active');
}

function closeModal(modalId) {
    document.getElementById(modalId).classList.remove('active');
}

// Close modal on background click
document.querySelectorAll('.modal').forEach(modal => {
    modal.addEventListener('click', function(e) {
        if (e.target === this) {
            this.classList.remove('active');
        }
    });
});

// Close buttons
document.querySelectorAll('.close-btn, [data-modal]').forEach(btn => {
    btn.addEventListener('click', function() {
        const modalId = this.dataset.modal;
        if (modalId) {
            closeModal(modalId);
        }
    });
});

// Add Task
document.getElementById('add-task-btn').addEventListener('click', () => openModal('task-modal'));

document.getElementById('task-form').addEventListener('submit', function(e) {
    e.preventDefault();

    const task = {
        id: Date.now(),
        title: document.getElementById('task-title').value,
        description: document.getElementById('task-description').value,
        dueDate: document.getElementById('task-date').value,
        priority: document.getElementById('task-priority').value,
        completed: false
    };

    appData.tasks.push(task);
    saveData();
    updateTasks();
    updateDashboard();

    closeModal('task-modal');
    this.reset();
    showNotification('Task added successfully!');
});

// Add Grade
document.getElementById('add-grade-btn').addEventListener('click', () => openModal('grade-modal'));

document.getElementById('grade-form').addEventListener('submit', function(e) {
    e.preventDefault();

    const grade = {
        id: Date.now(),
        course: document.getElementById('course-name').value,
        grade: parseFloat(document.getElementById('grade-value').value),
        credits: parseInt(document.getElementById('grade-credits').value),
        date: new Date().toISOString().split('T')[0]
    };

    appData.grades.push(grade);
    saveData();
    updatePerformance();
    updateDashboard();

    closeModal('grade-modal');
    this.reset();
    showNotification('Grade added successfully!');
});

// Notification
function showNotification(message) {
    // Create notification element
    const notification = document.createElement('div');
    notification.style.cssText = `
        position: fixed;
        top: 20px;
        right: 20px;
        background: #10b981;
        color: white;
        padding: 1rem 1.5rem;
        border-radius: 8px;
        box-shadow: 0 10px 15px rgba(0, 0, 0, 0.2);
        z-index: 10000;
        animation: slideIn 0.3s ease;
    `;
    notification.textContent = message;

    document.body.appendChild(notification);

    setTimeout(() => {
        notification.style.animation = 'slideOut 0.3s ease';
        setTimeout(() => notification.remove(), 300);
    }, 3000);
}

// Add animations
const style = document.createElement('style');
style.textContent = `
    @keyframes slideIn {
        from {
            transform: translateX(400px);
            opacity: 0;
        }
        to {
            transform: translateX(0);
            opacity: 1;
        }
    }

    @keyframes slideOut {
        from {
            transform: translateX(0);
            opacity: 1;
        }
        to {
            transform: translateX(400px);
            opacity: 0;
        }
    }
`;
document.head.appendChild(style);

// Initialize app
document.addEventListener('DOMContentLoaded', function() {
    loadData();
    updateDashboard();

    // Set initial mood button
    document.querySelector('.mood-btn[data-mood="3"]').classList.add('selected');
});

