// Data Storage
let appData = {
    tasks: [],
    grades: [],
    mentalHealth: [],
    initialized: false
};

// Load data from localStorage
function loadData() {
    const stored = localStorage.getItem('swmsData');
    if (stored) {
        appData = JSON.parse(stored);
    }
    if (!appData.initialized) {
        initializeSampleData();
    }
}

// Save data to localStorage
function saveData() {
    localStorage.setItem('swmsData', JSON.stringify(appData));
}

// Initialize with sample data
function initializeSampleData() {
    const today = new Date();
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);
    const nextWeek = new Date(today);
    nextWeek.setDate(nextWeek.getDate() + 7);

    appData.tasks = [
        {
            id: Date.now(),
            title: 'Complete Data Structures Assignment',
            description: 'Implement binary search tree',
            dueDate: tomorrow.toISOString().split('T')[0],
            priority: 'high',
            completed: false
        },
        {
            id: Date.now() + 1,
            title: 'Study for Calculus Midterm',
            description: 'Review chapters 5-8',
            dueDate: nextWeek.toISOString().split('T')[0],
            priority: 'high',
            completed: false
        },
        {
            id: Date.now() + 2,
            title: 'Read Psychology Chapter 3',
            description: 'Cognitive development theories',
            dueDate: nextWeek.toISOString().split('T')[0],
            priority: 'medium',
            completed: false
        }
    ];

    appData.grades = [
        { id: Date.now(), course: 'Data Structures', grade: 3.7, credits: 4, date: '2026-09-01' },
        { id: Date.now() + 1, course: 'Calculus II', grade: 3.5, credits: 4, date: '2026-09-05' },
        { id: Date.now() + 2, course: 'Psychology', grade: 3.9, credits: 3, date: '2026-09-10' },
        { id: Date.now() + 3, course: 'English Literature', grade: 3.8, credits: 3, date: '2026-09-12' }
    ];

    appData.mentalHealth = [
        { date: '2026-09-12', stress: 6, anxiety: 5, mood: 3, sleep: 6.5 },
        { date: '2026-09-13', stress: 7, anxiety: 6, mood: 3, sleep: 6 },
        { date: '2026-09-14', stress: 5, anxiety: 4, mood: 4, sleep: 7.5 },
        { date: '2026-09-15', stress: 8, anxiety: 7, mood: 2, sleep: 5.5 },
        { date: '2026-09-16', stress: 6, anxiety: 5, mood: 3, sleep: 7 },
        { date: '2026-09-17', stress: 4, anxiety: 3, mood: 4, sleep: 8 },
        { date: '2026-09-18', stress: 5, anxiety: 4, mood: 4, sleep: 7.5 }
    ];

    appData.initialized = true;
    saveData();
}

// Navigation
document.querySelectorAll('.nav-item').forEach(item => {
    item.addEventListener('click', function() {
        const view = this.dataset.view;
        switchView(view);

        document.querySelectorAll('.nav-item').forEach(nav => nav.classList.remove('active'));
        this.classList.add('active');
    });
});

function switchView(viewName) {
    document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
    document.getElementById(`${viewName}-view`).classList.add('active');

    // Update view-specific content
    if (viewName === 'dashboard') updateDashboard();
    if (viewName === 'performance') updatePerformance();
    if (viewName === 'mental-health') updateMentalHealth();
    if (viewName === 'tasks') updateTasks();
}

// Dashboard Functions
function updateDashboard() {
    // Update date
    const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    document.getElementById('current-date').textContent = new Date().toLocaleDateString('en-US', options);

    // Update stats
    const pendingTasks = appData.tasks.filter(t => !t.completed).length;
    document.getElementById('pending-tasks').textContent = pendingTasks;

    const gpa = calculateGPA();
    document.getElementById('current-gpa').textContent = gpa.toFixed(2);

    const completionRate = calculateCompletionRate();
    document.getElementById('completion-rate').textContent = completionRate + '%';

    const stressLevel = getLatestStressLevel();
    document.getElementById('stress-level').textContent = stressLevel.label;
    const stressCard = document.querySelector('.stress-card');
    stressCard.classList.remove('low', 'medium', 'high');
    stressCard.classList.add(stressLevel.class);

    // Update upcoming deadlines
    updateUpcomingDeadlines();

    // Update workload chart
    createWorkloadChart();
}

function calculateGPA() {
    if (appData.grades.length === 0) return 0;
    const totalPoints = appData.grades.reduce((sum, g) => sum + (g.grade * g.credits), 0);
    const totalCredits = appData.grades.reduce((sum, g) => sum + g.credits, 0);
    return totalCredits > 0 ? totalPoints / totalCredits : 0;
}

function calculateCompletionRate() {
    if (appData.tasks.length === 0) return 0;
    const completed = appData.tasks.filter(t => t.completed).length;
    return Math.round((completed / appData.tasks.length) * 100);
}

function getLatestStressLevel() {
    if (appData.mentalHealth.length === 0) return { label: 'Unknown', class: 'low' };
    const latest = appData.mentalHealth[appData.mentalHealth.length - 1];
    const stress = latest.stress;

    if (stress <= 3) return { label: 'Low', class: 'low' };
    if (stress <= 6) return { label: 'Medium', class: 'medium' };
    return { label: 'High', class: 'high' };
}

function updateUpcomingDeadlines() {
    const container = document.getElementById('deadlines-list');
    const upcomingTasks = appData.tasks
        .filter(t => !t.completed)
        .sort((a, b) => new Date(a.dueDate) - new Date(b.dueDate))
        .slice(0, 5);

    if (upcomingTasks.length === 0) {
        container.innerHTML = '<p class="empty-state">No upcoming deadlines</p>';
        return;
    }

    container.innerHTML = upcomingTasks.map(task => {
        const daysUntil = getDaysUntilDue(task.dueDate);
        return `
            <div class="deadline-item ${task.priority}">
                <h4>${task.title}</h4>
                <p>📅 ${formatDate(task.dueDate)} (${daysUntil})</p>
            </div>
        `;
    }).join('');
}

function getDaysUntilDue(dueDate) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const due = new Date(dueDate);
    due.setHours(0, 0, 0, 0);
    const diff = Math.ceil((due - today) / (1000 * 60 * 60 * 24));

    if (diff < 0) return 'Overdue';
    if (diff === 0) return 'Due today';
    if (diff === 1) return 'Due tomorrow';
    return `${diff} days left`;
}

function formatDate(dateString) {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}

// Chart Functions
function createWorkloadChart() {
    const ctx = document.getElementById('workloadChart');
    if (!ctx) return;

    // Clear existing chart
    if (window.workloadChartInstance) {
        window.workloadChartInstance.destroy();
    }

    const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
    const data = [5, 7, 6, 8, 9, 4, 3]; // Sample workload hours

    // Simple bar chart using canvas
    const canvas = ctx;
    canvas.width = canvas.offsetWidth;
    canvas.height = 250;
    const context = canvas.getContext('2d');

    const barWidth = canvas.width / days.length;
    const maxHeight = canvas.height - 40;
    const maxValue = Math.max(...data);

    context.clearRect(0, 0, canvas.width, canvas.height);

    data.forEach((value, index) => {
        const barHeight = (value / maxValue) * maxHeight;
        const x = index * barWidth + 10;
        const y = canvas.height - barHeight - 20;

        // Draw bar
        context.fillStyle = '#6366f1';
        context.fillRect(x, y, barWidth - 20, barHeight);

        // Draw label
        context.fillStyle = '#cbd5e1';
        context.font = '12px sans-serif';
        context.textAlign = 'center';
        context.fillText(days[index], x + (barWidth - 20) / 2, canvas.height - 5);

        // Draw value
        context.fillText(value + 'h', x + (barWidth - 20) / 2, y - 5);
    });
}

