// Tasks Functions
function updateTasks(filter = 'all') {
    const container = document.getElementById('tasks-list');
    let tasksToShow = appData.tasks;

    if (filter === 'pending') {
        tasksToShow = appData.tasks.filter(t => !t.completed);
    } else if (filter === 'completed') {
        tasksToShow = appData.tasks.filter(t => t.completed);
    }

    if (tasksToShow.length === 0) {
        container.innerHTML = '<p class="empty-state">No tasks found</p>';
        return;
    }

    // Sort by due date
    tasksToShow.sort((a, b) => new Date(a.dueDate) - new Date(b.dueDate));

    container.innerHTML = tasksToShow.map(task => {
        const daysUntil = getDaysUntilDue(task.dueDate);
        return `
            <div class="task-item ${task.priority} ${task.completed ? 'completed' : ''}" data-task-id="${task.id}">
                <div class="task-checkbox ${task.completed ? 'checked' : ''}" onclick="toggleTask(${task.id})"></div>
                <div class="task-content">
                    <h4>${task.title}</h4>
                    ${task.description ? `<p>${task.description}</p>` : ''}
                    <div class="task-meta">
                        <span>📅 ${formatDate(task.dueDate)}</span>
                        <span>${daysUntil}</span>
                        <span class="priority-badge">${task.priority.toUpperCase()}</span>
                    </div>
                </div>
                <div class="task-actions">
                    <button class="icon-btn" onclick="deleteTask(${task.id})" title="Delete">🗑️</button>
                </div>
            </div>
        `;
    }).join('');
}

function toggleTask(taskId) {
    const task = appData.tasks.find(t => t.id === taskId);
    if (task) {
        task.completed = !task.completed;
        saveData();
        updateTasks();
        updateDashboard();
    }
}

function deleteTask(taskId) {
    if (confirm('Are you sure you want to delete this task?')) {
        appData.tasks = appData.tasks.filter(t => t.id !== taskId);
        saveData();
        updateTasks();
        updateDashboard();
        showNotification('Task deleted');
    }
}

