/* Reset and Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    -webkit-tap-highlight-color: transparent;
}

:root {
    --primary-color: #6bc4a6;
    --primary-dark: #4a9b82;
    --primary-light: #8ed4bc;
    --accent-color: #7d5a50;
    --accent-dark: #5c4038;
    --accent-light: #9d7a6f;
    --success-color: #6bc4a6;
    --warning-color: #d4a574;
    --danger-color: #c97064;
    --bg-primary: #f8f6f3;
    --bg-secondary: #ffffff;
    --bg-card: #fefdfb;
    --bg-accent: #f0ede8;
    --text-primary: #2d2520;
    --text-secondary: #5c4038;
    --text-muted: #9d7a6f;
    --border-color: #e8dfd7;
    --shadow: 0 2px 8px rgba(125, 90, 80, 0.08);
    --shadow-md: 0 4px 12px rgba(125, 90, 80, 0.12);
    --shadow-lg: 0 8px 24px rgba(125, 90, 80, 0.15);
}

html {
    touch-action: manipulation;
    -webkit-text-size-adjust: 100%;
}

body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background: var(--bg-primary);
    color: var(--text-primary);
    line-height: 1.6;
    overflow-x: hidden;
    font-size: 15px;
}

/* Mobile Header */
.mobile-header {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    height: 64px;
    background: var(--bg-secondary);
    border-bottom: 1px solid var(--border-color);
    align-items: center;
    justify-content: space-between;
    padding: 0 1.25rem;
    z-index: 999;
    backdrop-filter: blur(10px);
    background: rgba(255, 255, 255, 0.95);
}

.menu-toggle,
.settings-btn {
    background: transparent;
    border: none;
    color: var(--accent-color);
    font-size: 1.4rem;
    cursor: pointer;
    padding: 0.5rem;
    width: 44px;
    height: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 8px;
    transition: all 0.2s ease;
}

.menu-toggle:active,
.settings-btn:active {
    background: var(--bg-accent);
    transform: scale(0.95);
}

.mobile-title {
    font-size: 1.1rem;
    color: var(--accent-color);
    font-weight: 600;
    letter-spacing: -0.02em;
}

/* Sidebar Overlay */
.sidebar-overlay {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.7);
    z-index: 998;
    opacity: 0;
    transition: opacity 0.3s ease;
}

.sidebar-overlay.active {
    display: block;
    opacity: 1;
}

/* Daily Mood Check Modal */
.mood-check-modal {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.95);
    z-index: 10000;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}

.mood-check-modal.active {
    display: flex;
}

.mood-check-content {
    background: var(--bg-secondary);
    border-radius: 20px;
    padding: 2rem;
    max-width: 500px;
    width: 100%;
    animation: bounceIn 0.6s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

@keyframes bounceIn {
    0% {
        opacity: 0;
        transform: scale(0.3);
    }
    50% {
        opacity: 1;
        transform: scale(1.05);
    }
    70% {
        transform: scale(0.9);
    }
    100% {
        transform: scale(1);
    }
}

.mood-check-header {
    text-align: center;
    margin-bottom: 2rem;
}

.mood-check-header h2 {
    font-size: 1.75rem;
    margin-bottom: 0.5rem;
    color: var(--text-primary);
}

.mood-check-header p {
    color: var(--text-muted);
}

.mood-scale {
    margin-bottom: 2rem;
}

.mood-scale-labels {
    display: flex;
    justify-content: space-between;
    margin-bottom: 1rem;
    font-size: 0.9rem;
    color: var(--text-muted);
}

.mood-scale-numbers {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 0.5rem;
    margin-bottom: 2rem;
}

.mood-number {
    aspect-ratio: 1;
    border: 2px solid var(--border-color);
    background: var(--bg-card);
    color: var(--text-primary);
    border-radius: 12px;
    font-size: 1.25rem;
    font-weight: bold;
    cursor: pointer;
    transition: all 0.3s ease;
    position: relative;
    overflow: hidden;
}

.mood-number:active {
    transform: scale(0.95);
}

.mood-number.selected {
    border-color: var(--primary-color);
    background: var(--primary-color);
    color: white;
    animation: pulse 0.6s ease;
}

@keyframes pulse {
    0%, 100% {
        transform: scale(1);
    }
    50% {
        transform: scale(1.1);
    }
}

.mood-animation-container {
    position: relative;
    height: 150px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.mood-emoji-display {
    font-size: 5rem;
    animation: float 3s ease-in-out infinite;
    position: relative;
    z-index: 2;
}

@keyframes float {
    0%, 100% {
        transform: translateY(0px);
    }
    50% {
        transform: translateY(-20px);
    }
}

.mood-particles {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    pointer-events: none;
}

.particle {
    position: absolute;
    font-size: 1.5rem;
    animation: particleFloat 2s ease-out forwards;
    opacity: 0;
}

@keyframes particleFloat {
    0% {
        opacity: 1;
        transform: translateY(0) scale(0);
    }
    50% {
        opacity: 1;
        transform: translateY(-50px) scale(1);
    }
    100% {
        opacity: 0;
        transform: translateY(-100px) scale(0.5);
    }
}

/* App Container */
.app-container {
    display: flex;
    min-height: 100vh;
}

/* Sidebar */
.sidebar {
    width: 260px;
    background: var(--bg-secondary);
    border-right: 1px solid var(--border-color);
    display: flex;
    flex-direction: column;
    position: fixed;
    height: 100vh;
    overflow-y: auto;
    z-index: 1000;
    transition: transform 0.3s ease;
}

.logo {
    padding: 2rem 1.5rem 1.5rem;
    border-bottom: 1px solid var(--border-color);
}

.logo h2 {
    font-size: 1.4rem;
    color: var(--accent-color);
    margin-bottom: 0.25rem;
    font-weight: 700;
    letter-spacing: -0.03em;
}

.logo p {
    font-size: 0.8rem;
    color: var(--text-muted);
    font-weight: 500;
}

.nav-menu {
    flex: 1;
    padding: 1rem 0;
}

.nav-item {
    width: 100%;
    padding: 0.9rem 1.5rem;
    background: transparent;
    border: none;
    color: var(--text-secondary);
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.9rem;
    font-size: 0.95rem;
    transition: all 0.2s ease;
    border-left: 3px solid transparent;
    font-weight: 500;
    margin: 0.2rem 0;
}

.nav-item:hover {
    background: var(--bg-accent);
    color: var(--accent-color);
}

.nav-item.active {
    background: linear-gradient(90deg, rgba(107, 196, 166, 0.1) 0%, transparent 100%);
    color: var(--primary-color);
    border-left-color: var(--primary-color);
}

.nav-item .icon {
    font-size: 1.2rem;
}

.user-profile {
    padding: 1.25rem 1.5rem;
    border-top: 1px solid var(--border-color);
    display: flex;
    align-items: center;
    gap: 0.9rem;
}

.avatar {
    width: 42px;
    height: 42px;
    border-radius: 12px;
    background: linear-gradient(135deg, var(--primary-color) 0%, var(--primary-dark) 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.2rem;
}

.user-info h4 {
    font-size: 0.9rem;
    color: var(--text-primary);
    font-weight: 600;
}

.user-info p {
    font-size: 0.75rem;
    color: var(--text-muted);
    font-weight: 500;
}

/* Main Content */
.main-content {
    flex: 1;
    margin-left: 260px;
    padding: 2rem;
    max-width: 1400px;
}

.view {
    display: none;
}

.view.active {
    display: block;
    animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.header {
    margin-bottom: 2rem;
}

.header h1 {
    font-size: 2rem;
    margin-bottom: 0.5rem;
}

.header p {
    color: var(--text-muted);
}

.date {
    font-size: 0.9rem;
    color: var(--text-muted);
}

/* Stats Grid */
.stats-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 1.25rem;
    margin-bottom: 2rem;
}

.stat-card {
    background: var(--bg-card);
    padding: 1.5rem;
    border-radius: 16px;
    display: flex;
    align-items: center;
    gap: 1.25rem;
    border: 1px solid var(--border-color);
    transition: all 0.3s ease;
    position: relative;
    overflow: hidden;
}

.stat-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg, var(--primary-color) 0%, var(--primary-light) 100%);
    opacity: 0;
    transition: opacity 0.3s ease;
}

.stat-card:hover {
    transform: translateY(-2px);
    box-shadow: var(--shadow-md);
}

.stat-card:hover::before {
    opacity: 1;
}

.stat-icon {
    font-size: 2.5rem;
    background: linear-gradient(135deg, var(--bg-accent) 0%, rgba(107, 196, 166, 0.1) 100%);
    width: 60px;
    height: 60px;
    border-radius: 14px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.stat-info h3 {
    font-size: 1.85rem;
    color: var(--accent-color);
    margin-bottom: 0.25rem;
    font-weight: 700;
    letter-spacing: -0.02em;
}

.stat-info p {
    color: var(--text-muted);
    font-size: 0.85rem;
    font-weight: 500;
}

.stress-card.high::before {
    background: linear-gradient(90deg, var(--danger-color) 0%, #e89b94 100%);
}

.stress-card.medium::before {
    background: linear-gradient(90deg, var(--warning-color) 0%, #e8c9a0 100%);
}

.stress-card.low::before {
    background: linear-gradient(90deg, var(--success-color) 0%, var(--primary-light) 100%);
}

/* Dashboard Grid */
.dashboard-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
    gap: 1.25rem;
}

.card {
    background: var(--bg-card);
    padding: 1.75rem;
    border-radius: 16px;
    border: 1px solid var(--border-color);
    transition: all 0.3s ease;
}

.card:hover {
    box-shadow: var(--shadow-md);
}

.card h3 {
    font-size: 1.15rem;
    margin-bottom: 1.5rem;
    color: var(--accent-color);
    font-weight: 600;
    letter-spacing: -0.01em;
}

.card-subtitle {
    color: var(--text-muted);
    font-size: 0.8rem;
    margin-top: -0.75rem;
    margin-bottom: 1.25rem;
    font-weight: 500;
}

/* Upcoming Deadlines */
.deadlines-list {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.deadline-item {
    padding: 1rem;
    background: var(--bg-card);
    border-radius: 8px;
    border-left: 4px solid var(--primary-color);
    transition: transform 0.2s ease;
}

.deadline-item:hover {
    transform: translateX(4px);
}

.deadline-item.high {
    border-left-color: var(--danger-color);
}

.deadline-item.medium {
    border-left-color: var(--warning-color);
}

.deadline-item.low {
    border-left-color: var(--success-color);
}

.deadline-item h4 {
    font-size: 1rem;
    margin-bottom: 0.5rem;
    color: var(--text-primary);
}

.deadline-item p {
    font-size: 0.85rem;
    color: var(--text-muted);
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

/* Recommendations */
.recommendations-list {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.recommendation-item {
    display: flex;
    align-items: flex-start;
    gap: 1rem;
    padding: 1rem;
    background: var(--bg-card);
    border-radius: 8px;
}

.rec-icon {
    font-size: 1.5rem;
}

.recommendation-item p {
    color: var(--text-secondary);
    font-size: 0.9rem;
}

/* Chart Container */
.chart-container {
    position: relative;
    height: 250px;
    margin-top: 1rem;
}

/* Performance Grid */
.performance-controls {
    margin-bottom: 2rem;
}

.performance-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
    gap: 1.5rem;
}

.gpa-display {
    text-align: center;
    margin-bottom: 2rem;
}

.gpa-value {
    font-size: 3rem;
    font-weight: bold;
    color: var(--primary-color);
}

.gpa-display p {
    color: var(--text-muted);
    margin-top: 0.5rem;
}

.grades-list {
    max-height: 400px;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.grade-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem;
    background: var(--bg-card);
    border-radius: 8px;
}

.grade-info h4 {
    font-size: 1rem;
    margin-bottom: 0.25rem;
}

.grade-info p {
    font-size: 0.85rem;
    color: var(--text-muted);
}

.grade-value {
    font-size: 1.5rem;
    font-weight: bold;
    color: var(--primary-color);
}

/* Completion Card */
.completion-stats {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 2rem;
    margin-top: 2rem;
}

.completion-circle {
    width: 150px;
    height: 150px;
}

.circular-chart {
    width: 100%;
    height: 100%;
}

.circle-bg {
    fill: none;
    stroke: var(--bg-card);
    stroke-width: 3.8;
}

.circle {
    fill: none;
    stroke: var(--primary-color);
    stroke-width: 2.8;
    stroke-linecap: round;
    animation: progress 1s ease-out forwards;
}

@keyframes progress {
    0% {
        stroke-dasharray: 0 100;
    }
}

.percentage {
    fill: var(--text-primary);
    font-size: 0.5rem;
    font-weight: bold;
    text-anchor: middle;
}

.completion-details p {
    font-size: 1rem;
    margin-bottom: 0.5rem;
    color: var(--text-secondary);
}

.completion-details strong {
    color: var(--primary-color);
    font-size: 1.25rem;
}

/* Mental Health Grid */
.mental-health-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
    gap: 1.5rem;
}

/* Assessment Form */
.form-group {
    margin-bottom: 1.5rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.75rem;
    color: var(--text-primary);
    font-weight: 500;
}

.slider-container {
    margin-top: 0.5rem;
}

.slider {
    width: 100%;
    height: 8px;
    border-radius: 5px;
    background: var(--bg-card);
    outline: none;
    -webkit-appearance: none;
}

.slider::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    background: var(--primary-color);
    cursor: pointer;
}

.slider::-moz-range-thumb {
    width: 20px;
    height: 20px;
    border-radius: 50%;
    background: var(--primary-color);
    cursor: pointer;
    border: none;
}

.slider-labels {
    display: flex;
    justify-content: space-between;
    margin-top: 0.5rem;
    color: var(--text-muted);
    font-size: 0.85rem;
}

.slider-labels span:nth-child(2) {
    color: var(--primary-color);
    font-weight: bold;
    font-size: 1rem;
}

.mood-selector {
    display: flex;
    gap: 1rem;
    justify-content: center;
}

.mood-btn {
    background: var(--bg-card);
    border: 2px solid transparent;
    border-radius: 50%;
    width: 50px;
    height: 50px;
    font-size: 1.5rem;
    cursor: pointer;
    transition: all 0.3s ease;
}

.mood-btn:hover {
    transform: scale(1.1);
    border-color: var(--primary-color);
}

.mood-btn.selected {
    border-color: var(--primary-color);
    background: var(--primary-dark);
    transform: scale(1.1);
}

.input-field {
    width: 100%;
    padding: 0.75rem;
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    color: var(--text-primary);
    font-size: 1rem;
    transition: border-color 0.3s ease;
}

.input-field:focus {
    outline: none;
    border-color: var(--primary-color);
}

textarea.input-field {
    resize: vertical;
    font-family: inherit;
}

/* Wellness Tips */
.tips-list {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.tip-item {
    display: flex;
    gap: 1rem;
    padding: 1rem;
    background: var(--bg-card);
    border-radius: 8px;
}

.tip-icon {
    font-size: 2rem;
}

.tip-item h4 {
    font-size: 0.95rem;
    margin-bottom: 0.25rem;
    color: var(--text-primary);
}

.tip-item p {
    font-size: 0.85rem;
    color: var(--text-muted);
}

/* Mood History */
.mood-history-list {
    max-height: 400px;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.mood-history-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem;
    background: var(--bg-card);
    border-radius: 8px;
}

.mood-history-item .mood-emoji {
    font-size: 2rem;
}

.mood-history-item .mood-details {
    flex: 1;
    margin-left: 1rem;
}

.mood-history-item .mood-details p {
    font-size: 0.85rem;
    color: var(--text-muted);
}

/* Tasks */
.tasks-controls {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 1rem;
}

.filter-buttons {
    display: flex;
    gap: 0.5rem;
}

.filter-btn {
    padding: 0.5rem 1rem;
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    color: var(--text-secondary);
    cursor: pointer;
    transition: all 0.3s ease;
}

.filter-btn:hover {
    background: var(--bg-secondary);
    color: var(--text-primary);
}

.filter-btn.active {
    background: var(--primary-color);
    color: white;
    border-color: var(--primary-color);
}

.tasks-grid {
    display: grid;
    gap: 1.5rem;
}

.tasks-list {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.task-item {
    padding: 1.5rem;
    background: var(--bg-card);
    border-radius: 8px;
    border-left: 4px solid var(--primary-color);
    display: flex;
    align-items: flex-start;
    gap: 1rem;
    transition: transform 0.2s ease;
}

.task-item:hover {
    transform: translateX(4px);
}

.task-item.high {
    border-left-color: var(--danger-color);
}

.task-item.medium {
    border-left-color: var(--warning-color);
}

.task-item.low {
    border-left-color: var(--success-color);
}

.task-item.completed {
    opacity: 0.6;
}

.task-item.completed .task-content h4,
.task-item.completed .task-content p {
    text-decoration: line-through;
}

.task-checkbox {
    width: 24px;
    height: 24px;
    min-width: 24px;
    border: 2px solid var(--border-color);
    border-radius: 6px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--bg-secondary);
    transition: all 0.3s ease;
}

.task-checkbox:hover {
    border-color: var(--primary-color);
}

.task-checkbox.checked {
    background: var(--primary-color);
    border-color: var(--primary-color);
}

.task-checkbox.checked::after {
    content: '✓';
    color: white;
    font-weight: bold;
}

.task-content {
    flex: 1;
}

.task-content h4 {
    font-size: 1.1rem;
    margin-bottom: 0.5rem;
    color: var(--text-primary);
}

.task-content p {
    font-size: 0.9rem;
    color: var(--text-muted);
    margin-bottom: 0.5rem;
}

.task-meta {
    display: flex;
    gap: 1rem;
    font-size: 0.85rem;
    color: var(--text-muted);
}

.task-actions {
    display: flex;
    gap: 0.5rem;
}

.icon-btn {
    background: transparent;
    border: none;
    color: var(--text-muted);
    cursor: pointer;
    padding: 0.25rem;
    transition: color 0.3s ease;
}

.icon-btn:hover {
    color: var(--danger-color);
}

/* Buttons */
.btn {
    padding: 0.85rem 1.75rem;
    border: none;
    border-radius: 12px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
    letter-spacing: -0.01em;
}

.btn-primary {
    background: linear-gradient(135deg, var(--primary-color) 0%, var(--primary-dark) 100%);
    color: white;
    box-shadow: 0 2px 8px rgba(107, 196, 166, 0.25);
}

.btn-primary:active {
    transform: translateY(1px);
    box-shadow: 0 1px 4px rgba(107, 196, 166, 0.2);
}

.btn-secondary {
    background: var(--bg-accent);
    color: var(--accent-color);
    border: 1px solid var(--border-color);
}

.btn-secondary:active {
    background: var(--border-color);
}

.btn-block {
    width: 100%;
    margin-top: 1rem;
}

/* Modal */
.modal {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.7);
    z-index: 1000;
    align-items: center;
    justify-content: center;
}

.modal.active {
    display: flex;
}

.modal-content {
    background: var(--bg-secondary);
    border-radius: 12px;
    border: 1px solid var(--border-color);
    width: 90%;
    max-width: 500px;
    max-height: 90vh;
    overflow-y: auto;
    animation: slideUp 0.3s ease;
}

@keyframes slideUp {
    from {
        opacity: 0;
        transform: translateY(50px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.modal-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1.5rem;
    border-bottom: 1px solid var(--border-color);
}

.modal-header h2 {
    font-size: 1.5rem;
    color: var(--text-primary);
}

.close-btn {
    background: transparent;
    border: none;
    font-size: 2rem;
    color: var(--text-muted);
    cursor: pointer;
    line-height: 1;
    transition: color 0.3s ease;
}

.close-btn:hover {
    color: var(--text-primary);
}

.modal form {
    padding: 1.5rem;
}

.modal-actions {
    display: flex;
    gap: 1rem;
    margin-top: 1.5rem;
}

.modal-actions button {
    flex: 1;
}

/* Empty State */
.empty-state {
    text-align: center;
    color: var(--text-muted);
    padding: 2rem;
    font-style: italic;
}

/* Polygon Graph */
.polygon-container {
    position: relative;
    height: 350px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.polygon-container canvas {
    max-width: 100%;
    cursor: pointer;
}

.polygon-tooltip {
    position: absolute;
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    padding: 0.75rem;
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.3s ease;
    z-index: 10;
    box-shadow: var(--shadow-lg);
}

.polygon-tooltip.active {
    opacity: 1;
}

.card-subtitle {
    color: var(--text-muted);
    font-size: 0.85rem;
    margin-top: -0.5rem;
    margin-bottom: 1rem;
}

/* Settings */
.settings-grid {
    display: grid;
    gap: 1.5rem;
}

.setting-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem;
    background: var(--bg-card);
    border-radius: 8px;
    gap: 1rem;
}

.setting-info {
    flex: 1;
}

.setting-info h4 {
    font-size: 1rem;
    margin-bottom: 0.25rem;
    color: var(--text-primary);
}

.setting-info p {
    font-size: 0.85rem;
    color: var(--text-muted);
}

/* Toggle Switch */
.toggle-switch {
    position: relative;
    display: inline-block;
    width: 50px;
    height: 28px;
    flex-shrink: 0;
}

.toggle-switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.toggle-slider {
    position: absolute;
    cursor: pointer;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: var(--bg-primary);
    transition: 0.4s;
    border-radius: 28px;
    border: 2px solid var(--border-color);
}

.toggle-slider:before {
    position: absolute;
    content: "";
    height: 20px;
    width: 20px;
    left: 2px;
    bottom: 2px;
    background-color: var(--text-muted);
    transition: 0.4s;
    border-radius: 50%;
}

input:checked + .toggle-slider {
    background-color: var(--primary-color);
    border-color: var(--primary-color);
}

input:checked + .toggle-slider:before {
    transform: translateX(22px);
    background-color: white;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}

::-webkit-scrollbar-track {
    background: var(--bg-card);
}

::-webkit-scrollbar-thumb {
    background: var(--border-color);
    border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
    background: var(--text-muted);
}

/* Responsive Design */
@media (max-width: 768px) {
    .mobile-header {
        display: flex;
    }

    body {
        padding-top: 60px;
    }

    .sidebar {
        transform: translateX(-100%);
        width: 280px;
        top: 60px;
        height: calc(100vh - 60px);
    }

    .sidebar.active {
        transform: translateX(0);
    }

    .main-content {
        margin-left: 0;
        padding: 1rem;
    }

    .stats-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 1rem;
    }

    .stat-card {
        padding: 1rem;
    }

    .stat-icon {
        font-size: 2rem;
        width: 50px;
        height: 50px;
    }

    .stat-info h3 {
        font-size: 1.5rem;
    }

    .dashboard-grid,
    .performance-grid,
    .mental-health-grid,
    .settings-grid {
        grid-template-columns: 1fr;
    }

    .tasks-controls {
        flex-direction: column;
        align-items: stretch;
        gap: 0.75rem;
    }

    .filter-buttons {
        width: 100%;
        justify-content: space-between;
    }

    .filter-btn {
        flex: 1;
        padding: 0.5rem;
        font-size: 0.9rem;
    }

    .completion-stats {
        flex-direction: column;
    }

    .modal-content {
        width: 95%;
        max-width: none;
    }

    .mood-check-content {
        padding: 1.5rem;
    }

    .mood-scale-numbers {
        grid-template-columns: repeat(5, 1fr);
        gap: 0.4rem;
    }

    .mood-number {
        font-size: 1rem;
    }

    .mood-emoji-display {
        font-size: 4rem;
    }

    .card h3 {
        font-size: 1.1rem;
    }

    .setting-item {
        flex-direction: column;
        align-items: flex-start;
    }

    .setting-item .toggle-switch,
    .setting-item .input-field {
        align-self: flex-end;
    }

    .polygon-container {
        height: 280px;
    }
}

@media (max-width: 480px) {
    .stats-grid {
        grid-template-columns: 1fr;
    }

    .mood-scale-numbers {
        grid-template-columns: repeat(5, 1fr);
    }

    .header h1 {
        font-size: 1.5rem;
    }
}

/* Prevent pull-to-refresh on mobile */
body {
    overscroll-behavior-y: contain;
}

/* Smooth touch interactions */
button, .nav-item, .task-checkbox, .mood-number {
    touch-action: manipulation;
    -webkit-user-select: none;
    user-select: none;
}

