    border-radius: 50%;
}

.illustration-content {
    position: relative;
    z-index: 1;
    color: white;
    max-width: 500px;
}

.illustration-content h2 {
    font-size: 2.5rem;
    margin-bottom: 1rem;
    font-weight: 700;
    letter-spacing: -0.03em;
}

.illustration-content > p {
    font-size: 1.1rem;
    margin-bottom: 2.5rem;
    opacity: 0.95;
    line-height: 1.7;
}

.feature-list {
    display: grid;
    gap: 1.25rem;
}

.feature-item {
    display: flex;
    align-items: center;
    gap: 1rem;
    background: rgba(255, 255, 255, 0.15);
    padding: 1rem 1.25rem;
    border-radius: 12px;
    backdrop-filter: blur(10px);
    font-weight: 600;
    transition: all 0.3s ease;
}

.feature-item:hover {
    background: rgba(255, 255, 255, 0.2);
    transform: translateX(5px);
}

.feature-icon {
    font-size: 1.75rem;
}

@media (max-width: 968px) {
    .login-illustration {
        display: none;
    }

    .login-container {
        padding: 1.5rem;
    }
}

@media (max-width: 480px) {
    .login-form {
        padding: 1.5rem;
    }

    .login-header h1 {
        font-size: 1.5rem;
    }

    .social-login {
        grid-template-columns: 1fr;
    }
}

