// Load data from localStorage
function loadData() {
    const stored = localStorage.getItem('swmsData');
    if (stored) {
        appData = JSON.parse(stored);
    }
    if (!appData.initialized) {
        initializeSampleData();
    }
}

// Save data to localStorage
function saveData() {
    localStorage.setItem('swmsData', JSON.stringify(appData));
}

// Initialize with sample data
function initializeSampleData() {
    const today = new Date();
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);
    const nextWeek = new Date(today);
    nextWeek.setDate(nextWeek.getDate() + 7);

    appData.tasks = [
        {
            id: Date.now(),
            title: 'Complete Data Structures Assignment',
            description: 'Implement binary search tree',
            dueDate: tomorrow.toISOString().split('T')[0],
            priority: 'high',
            completed: false
        },
        {
            id: Date.now() + 1,
            title: 'Study for Calculus Midterm',
            description: 'Review chapters 5-8',
            dueDate: nextWeek.toISOString().split('T')[0],
            priority: 'high',
            completed: false
        },
        {
            id: Date.now() + 2,
            title: 'Read Psychology Chapter 3',
            description: 'Cognitive development theories',
            dueDate: nextWeek.toISOString().split('T')[0],
            priority: 'medium',
            completed: false
        }
    ];

    appData.grades = [
        { id: Date.now(), course: 'Data Structures', grade: 3.7, credits: 4, date: '2026-09-01' },
        { id: Date.now() + 1, course: 'Calculus II', grade: 3.5, credits: 4, date: '2026-09-05' },
        { id: Date.now() + 2, course: 'Psychology', grade: 3.9, credits: 3, date: '2026-09-10' },
        { id: Date.now() + 3, course: 'English Literature', grade: 3.8, credits: 3, date: '2026-09-12' }
    ];

    appData.mentalHealth = [
        { date: '2026-09-12', stress: 6, anxiety: 5, mood: 3, sleep: 6.5 },
        { date: '2026-09-13', stress: 7, anxiety: 6, mood: 3, sleep: 6 },
        { date: '2026-09-14', stress: 5, anxiety: 4, mood: 4, sleep: 7.5 },
        { date: '2026-09-15', stress: 8, anxiety: 7, mood: 2, sleep: 5.5 },
        { date: '2026-09-16', stress: 6, anxiety: 5, mood: 3, sleep: 7 },
        { date: '2026-09-17', stress: 4, anxiety: 3, mood: 4, sleep: 8 },
        { date: '2026-09-18', stress: 5, anxiety: 4, mood: 4, sleep: 7.5 }
    ];

    appData.initialized = true;
    saveData();
}

// Navigation
document.querySelectorAll('.nav-item').forEach(item => {
    item.addEventListener('click', function() {
        const view = this.dataset.view;
        switchView(view);

        document.querySelectorAll('.nav-item').forEach(nav => nav.classList.remove('active'));
        this.classList.add('active');
    });
});

function switchView(viewName) {
    document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
    document.getElementById(`${viewName}-view`).classList.add('active');

    // Update view-specific content
    if (viewName === 'dashboard') updateDashboard();
    if (viewName === 'performance') updatePerformance();
    if (viewName === 'mental-health') updateMentalHealth();
    if (viewName === 'tasks') updateTasks();
}

// Dashboard Functions
function updateDashboard() {
    // Update date
    const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    document.getElementById('current-date').textContent = new Date().toLocaleDateString('en-US', options);

    // Update stats
    const pendingTasks = appData.tasks.filter(t => !t.completed).length;
    document.getElementById('pending-tasks').textContent = pendingTasks;

    const gpa = calculateGPA();
    document.getElementById('current-gpa').textContent = gpa.toFixed(2);

    const completionRate = calculateCompletionRate();
    document.getElementById('completion-rate').textContent = completionRate + '%';

    const stressLevel = getLatestStressLevel();
    document.getElementById('stress-level').textContent = stressLevel.label;
    const stressCard = document.querySelector('.stress-card');
    stressCard.classList.remove('low', 'medium', 'high');
    stressCard.classList.add(stressLevel.class);

    // Update upcoming deadlines
    updateUpcomingDeadlines();

    // Create polygon graph
    createPolygonGraph();
}

function calculateGPA() {
    if (appData.grades.length === 0) return 0;
    const totalPoints = appData.grades.reduce((sum, g) => sum + (g.grade * g.credits), 0);
    const totalCredits = appData.grades.reduce((sum, g) => sum + g.credits, 0);
    return totalCredits > 0 ? totalPoints / totalCredits : 0;
}

function calculateCompletionRate() {
    if (appData.tasks.length === 0) return 0;
    const completed = appData.tasks.filter(t => t.completed).length;
    return Math.round((completed / appData.tasks.length) * 100);
}

function getLatestStressLevel() {
    if (appData.mentalHealth.length === 0) return { label: 'Unknown', class: 'low' };
    const latest = appData.mentalHealth[appData.mentalHealth.length - 1];
    const stress = latest.stress;

    if (stress <= 3) return { label: 'Low', class: 'low' };
    if (stress <= 6) return { label: 'Medium', class: 'medium' };
    return { label: 'High', class: 'high' };
}

function updateUpcomingDeadlines() {
    const container = document.getElementById('deadlines-list');
    const upcomingTasks = appData.tasks
        .filter(t => !t.completed)
        .sort((a, b) => new Date(a.dueDate) - new Date(b.dueDate))
        .slice(0, 5);

    if (upcomingTasks.length === 0) {
        container.innerHTML = '<p class="empty-state">No upcoming deadlines</p>';
        return;
    }

    container.innerHTML = upcomingTasks.map(task => {
        const daysUntil = getDaysUntilDue(task.dueDate);
        return `
            <div class="deadline-item ${task.priority}">
                <h4>${task.title}</h4>
                <p>📅 ${formatDate(task.dueDate)} (${daysUntil})</p>
            </div>
        `;
    }).join('');
}

function getDaysUntilDue(dueDate) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const due = new Date(dueDate);
    due.setHours(0, 0, 0, 0);
    const diff = Math.ceil((due - today) / (1000 * 60 * 60 * 24));

    if (diff < 0) return 'Overdue';
    if (diff === 0) return 'Due today';
    if (diff === 1) return 'Due tomorrow';
    return `${diff} days left`;
}

function formatDate(dateString) {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}

// Chart Functions
function createPolygonGraph() {
    const canvas = document.getElementById('weeklyPolygon');
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    const tooltip = document.getElementById('polygon-tooltip');

    // Set canvas size
    const size = Math.min(canvas.parentElement.offsetWidth, 350);
    canvas.width = size;
    canvas.height = size;

    const centerX = size / 2;
    const centerY = size / 2;
    const radius = size * 0.35;

    // Weekly metrics (0-100 scale)
    const metrics = [
        { label: 'Mon', value: calculateDayScore(1), color: '#6366f1' },
        { label: 'Tue', value: calculateDayScore(2), color: '#8b5cf6' },
        { label: 'Wed', value: calculateDayScore(3), color: '#ec4899' },
        { label: 'Thu', value: calculateDayScore(4), color: '#f59e0b' },
        { label: 'Fri', value: calculateDayScore(5), color: '#10b981' },
        { label: 'Sat', value: calculateDayScore(6), color: '#3b82f6' },
        { label: 'Sun', value: calculateDayScore(0), color: '#a855f7' }
    ];

    const points = [];
    const angleStep = (Math.PI * 2) / metrics.length;

    ctx.clearRect(0, 0, size, size);

    // Draw background circles
    ctx.strokeStyle = '#475569';
    ctx.lineWidth = 1;
    for (let i = 1; i <= 5; i++) {
        ctx.beginPath();
        ctx.arc(centerX, centerY, (radius / 5) * i, 0, Math.PI * 2);
        ctx.stroke();
    }

    // Draw axis lines and labels
    ctx.strokeStyle = '#475569';
    ctx.fillStyle = '#94a3b8';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    metrics.forEach((metric, index) => {
        const angle = angleStep * index - Math.PI / 2;
        const x = centerX + Math.cos(angle) * radius;
        const y = centerY + Math.sin(angle) * radius;

        // Draw axis line
        ctx.beginPath();
        ctx.moveTo(centerX, centerY);
        ctx.lineTo(x, y);
        ctx.stroke();

        // Draw label
        const labelX = centerX + Math.cos(angle) * (radius + 20);
        const labelY = centerY + Math.sin(angle) * (radius + 20);
        ctx.fillText(metric.label, labelX, labelY);

        // Calculate point position
        const pointRadius = (metric.value / 100) * radius;
        const pointX = centerX + Math.cos(angle) * pointRadius;
        const pointY = centerY + Math.sin(angle) * pointRadius;
        points.push({ x: pointX, y: pointY, metric: metric });
    });

    // Draw filled polygon with gradient
    const gradient = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, radius);
    gradient.addColorStop(0, 'rgba(99, 102, 241, 0.4)');
    gradient.addColorStop(1, 'rgba(99, 102, 241, 0.1)');

    ctx.fillStyle = gradient;
    ctx.strokeStyle = '#6366f1';
    ctx.lineWidth = 3;
    ctx.beginPath();
    points.forEach((point, index) => {
        if (index === 0) {
            ctx.moveTo(point.x, point.y);
        } else {
            ctx.lineTo(point.x, point.y);
        }
    });
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    // Draw points with animation on touch/click
    points.forEach((point, index) => {
        ctx.fillStyle = point.metric.color;
        ctx.beginPath();
        ctx.arc(point.x, point.y, 6, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.stroke();
    });

    // Touch/Click interaction
    let animationFrame = null;
    let hoveredPoint = null;

    function handleInteraction(e) {
        const rect = canvas.getBoundingClientRect();
        const clientX = e.touches ? e.touches[0].clientX : e.clientX;
        const clientY = e.touches ? e.touches[0].clientY : e.clientY;
        const x = clientX - rect.left;
        const y = clientY - rect.top;

        // Scale coordinates
        const scaleX = canvas.width / rect.width;
        const scaleY = canvas.height / rect.height;
        const scaledX = x * scaleX;
        const scaledY = y * scaleY;

        // Find closest point
        let closest = null;
        let minDist = 30;

        points.forEach((point) => {
            const dist = Math.sqrt(Math.pow(point.x - scaledX, 2) + Math.pow(point.y - scaledY, 2));
            if (dist < minDist) {
                minDist = dist;
                closest = point;
            }
        });

        if (closest) {
            hoveredPoint = closest;

            // Show tooltip
            tooltip.innerHTML = `
                <strong>${closest.metric.label}</strong><br>
                Performance: ${closest.metric.value}%
            `;
            tooltip.style.left = (x + 10) + 'px';
            tooltip.style.top = (y - 40) + 'px';
            tooltip.classList.add('active');

            // Animate point
            if (animationFrame) cancelAnimationFrame(animationFrame);
            let scale = 1;
            let growing = true;

            function animate() {
                ctx.clearRect(0, 0, size, size);

                // Redraw everything
                drawPolygonBase();

                // Animate hovered point
                if (growing) {
                    scale += 0.05;
                    if (scale >= 1.5) growing = false;
                } else {
                    scale -= 0.05;
                    if (scale <= 1) growing = true;
                }

                ctx.save();
                ctx.translate(closest.x, closest.y);
                ctx.scale(scale, scale);
                ctx.translate(-closest.x, -closest.y);
                ctx.fillStyle = closest.metric.color;
                ctx.beginPath();
                ctx.arc(closest.x, closest.y, 6, 0, Math.PI * 2);
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.restore();

                animationFrame = requestAnimationFrame(animate);
            }
            animate();
        } else {
            hideTooltip();
        }
    }

    function hideTooltip() {
        tooltip.classList.remove('active');
        if (animationFrame) {
            cancelAnimationFrame(animationFrame);
            animationFrame = null;
        }
        hoveredPoint = null;
        createPolygonGraph(); // Redraw without animation
    }

    function drawPolygonBase() {
        // Redraw background
        ctx.strokeStyle = '#475569';
        ctx.lineWidth = 1;
        for (let i = 1; i <= 5; i++) {
            ctx.beginPath();
            ctx.arc(centerX, centerY, (radius / 5) * i, 0, Math.PI * 2);
            ctx.stroke();
        }

        // Redraw axes and labels
        ctx.strokeStyle = '#475569';
        ctx.fillStyle = '#94a3b8';
        metrics.forEach((metric, index) => {
            const angle = angleStep * index - Math.PI / 2;
            const x = centerX + Math.cos(angle) * radius;
            const y = centerY + Math.sin(angle) * radius;
            ctx.beginPath();
            ctx.moveTo(centerX, centerY);
            ctx.lineTo(x, y);
            ctx.stroke();
            const labelX = centerX + Math.cos(angle) * (radius + 20);
            const labelY = centerY + Math.sin(angle) * (radius + 20);
            ctx.fillText(metric.label, labelX, labelY);
        });

        // Redraw polygon
        const gradient = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, radius);
        gradient.addColorStop(0, 'rgba(99, 102, 241, 0.4)');
        gradient.addColorStop(1, 'rgba(99, 102, 241, 0.1)');
        ctx.fillStyle = gradient;
        ctx.strokeStyle = '#6366f1';
        ctx.lineWidth = 3;
        ctx.beginPath();
        points.forEach((point, index) => {
            if (index === 0) ctx.moveTo(point.x, point.y);
            else ctx.lineTo(point.x, point.y);
        });
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Redraw all points
        points.forEach(point => {
            if (point !== hoveredPoint) {
                ctx.fillStyle = point.metric.color;
                ctx.beginPath();
                ctx.arc(point.x, point.y, 6, 0, Math.PI * 2);
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
            }
        });
    }

    canvas.addEventListener('touchstart', handleInteraction);
    canvas.addEventListener('touchmove', handleInteraction);
    canvas.addEventListener('touchend', hideTooltip);
    canvas.addEventListener('mousemove', handleInteraction);
    canvas.addEventListener('mouseleave', hideTooltip);
    canvas.addEventListener('click', handleInteraction);
}

function calculateDayScore(dayOfWeek) {
    // Calculate a performance score for each day based on tasks and stress
    const today = new Date();
    const targetDay = new Date(today);
    const daysAgo = (today.getDay() - dayOfWeek + 7) % 7;
    targetDay.setDate(today.getDate() - daysAgo);
    const targetDate = targetDay.toISOString().split('T')[0];

    // Check tasks completed on that day
    const dayTasks = appData.tasks.filter(t => {
        return t.completed && t.completedDate === targetDate;
    });

    // Check mental health for that day
    const dayMentalHealth = appData.mentalHealth.find(m => m.date === targetDate);

    let score = 50; // Base score

    // Add points for completed tasks
    score += Math.min(dayTasks.length * 10, 30);

    // Add points for good mental health
    if (dayMentalHealth) {
        const stressImpact = (10 - dayMentalHealth.stress) * 2;
        const moodImpact = dayMentalHealth.mood * 2;
        score += (stressImpact + moodImpact) / 2;
    }

    // Random variation for demo
    score += Math.random() * 20 - 10;

    return Math.max(20, Math.min(100, score));
}

function createWorkloadChart() {
    const ctx = document.getElementById('workloadChart');
    if (!ctx) return;

    // Clear existing chart
    if (window.workloadChartInstance) {
        window.workloadChartInstance.destroy();
    }

    const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
    const data = [5, 7, 6, 8, 9, 4, 3]; // Sample workload hours

    // Simple bar chart using canvas
    const canvas = ctx;
    canvas.width = canvas.offsetWidth;
    canvas.height = 250;
    const context = canvas.getContext('2d');

    const barWidth = canvas.width / days.length;
    const maxHeight = canvas.height - 40;
    const maxValue = Math.max(...data);

    context.clearRect(0, 0, canvas.width, canvas.height);

    data.forEach((value, index) => {
        const barHeight = (value / maxValue) * maxHeight;
        const x = index * barWidth + 10;
        const y = canvas.height - barHeight - 20;

        // Draw bar
        context.fillStyle = '#6366f1';
        context.fillRect(x, y, barWidth - 20, barHeight);

        // Draw label
        context.fillStyle = '#cbd5e1';
        context.font = '12px sans-serif';
        context.textAlign = 'center';
        context.fillText(days[index], x + (barWidth - 20) / 2, canvas.height - 5);

        // Draw value
        context.fillText(value + 'h', x + (barWidth - 20) / 2, y - 5);
    });
}

