function createMoodParticles(moodValue, moodParticles, container) {
    // Clear existing particles
    container.innerHTML = '';

    const particles = moodParticles[moodValue] || ['✨'];
    const numParticles = Math.min(moodValue, 8);

    for (let i = 0; i < numParticles; i++) {
        setTimeout(() => {
            const particle = document.createElement('div');
            particle.className = 'particle';
            particle.textContent = particles[Math.floor(Math.random() * particles.length)];

            // Random position around the emoji
            const angle = (Math.PI * 2 / numParticles) * i;
            const radius = 60;
            const x = 50 + Math.cos(angle) * radius;
            const y = 50 + Math.sin(angle) * radius;

            particle.style.left = x + '%';
            particle.style.top = y + '%';

            container.appendChild(particle);

            setTimeout(() => particle.remove(), 2000);
        }, i * 100);
    }
}

