        const dataStr = JSON.stringify(appData, null, 2);
        const dataBlob = new Blob([dataStr], {type: 'application/json'});
        const url = URL.createObjectURL(dataBlob);
        const link = document.createElement('a');
        link.href = url;
        link.download = 'swms-data-' + new Date().toISOString().split('T')[0] + '.json';
        link.click();
        showNotification('Data exported successfully!');
    });

    // Clear data
    document.getElementById('clear-data-btn')?.addEventListener('click', () => {
        if (confirm('Are you sure you want to clear all data? This cannot be undone.')) {
            localStorage.removeItem('swmsData');
            showNotification('All data cleared. Refreshing...');
            setTimeout(() => location.reload(), 1500);
        }
    });
}

// Reminders System
function checkReminders() {
    if (!appData.settings.taskReminder) return;

    const now = new Date();
    const reminderWindowMs = appData.settings.reminderHours * 60 * 60 * 1000;

    appData.tasks.forEach(task => {
        if (task.completed || task.reminded) return;

        const dueDate = new Date(task.dueDate + 'T23:59:59');
        const timeDiff = dueDate - now;

        if (timeDiff > 0 && timeDiff <= reminderWindowMs) {
            const hours = Math.ceil(timeDiff / (60 * 60 * 1000));
            showNotification(`⏰ Reminder: "${task.title}" is due in ${hours} hour${hours !== 1 ? 's' : ''}!`);
            task.reminded = true;
            saveData();
        }
    });
}

