// Initialize app
document.addEventListener('DOMContentLoaded', function() {
    loadData();

    // Check if user is logged in
    if (appData.user.isLoggedIn) {
        showMainApp();
    } else {
        showLoginPage();
    }

    setupLoginHandlers();
    setupMobileNavigation();
    setupMoodCheckModal();
    setupSettings();

    // Set initial mood button
    document.querySelector('.mood-btn[data-mood="3"]')?.classList.add('selected');

    // Check reminders every minute
    setInterval(checkReminders, 60000);
});

// Login/Signup Handlers
function setupLoginHandlers() {
    const loginForm = document.getElementById('login-form');
    const signupForm = document.getElementById('signup-form');
    const showSignupLink = document.getElementById('show-signup');
    const showLoginLink = document.getElementById('show-login');
    const loginContent = document.querySelector('.login-content');
    const signupContent = document.querySelector('.signup-content');

    // Toggle between login and signup
    showSignupLink?.addEventListener('click', (e) => {
        e.preventDefault();
        loginContent.style.display = 'none';
        signupContent.style.display = 'block';
    });

    showLoginLink?.addEventListener('click', (e) => {
        e.preventDefault();
        signupContent.style.display = 'none';
        loginContent.style.display = 'block';
    });

    // Handle login
    loginForm?.addEventListener('submit', (e) => {
        e.preventDefault();
        const email = document.getElementById('login-email').value;
        const password = document.getElementById('login-password').value;
        const rememberMe = document.getElementById('remember-me').checked;

        // Simple validation (in real app, this would connect to backend)
        if (email && password) {
            appData.user.isLoggedIn = true;
            appData.user.email = email;
            appData.user.name = email.split('@')[0]; // Extract name from email
            saveData();

            showMainApp();
            showNotification('Welcome back! 🎉');
        }
    });

    // Handle signup
    signupForm?.addEventListener('submit', (e) => {
        e.preventDefault();
        const name = document.getElementById('signup-name').value;
        const email = document.getElementById('signup-email').value;
        const password = document.getElementById('signup-password').value;
        const confirm = document.getElementById('signup-confirm').value;

        if (password !== confirm) {
            showNotification('Passwords do not match!');
            return;
        }

        if (name && email && password) {
            appData.user.isLoggedIn = true;
            appData.user.name = name;
            appData.user.email = email;
            saveData();

            showMainApp();
            showNotification('Account created successfully! 🎉');
        }
    });
}

function showLoginPage() {
    document.getElementById('login-page').classList.add('active');
    document.querySelector('.app-container').style.display = 'none';
    document.querySelector('.mobile-header')?.style.display = 'none';
}

function showMainApp() {
    document.getElementById('login-page').classList.remove('active');
    document.querySelector('.app-container').style.display = 'flex';
    if (window.innerWidth <= 768) {
        document.querySelector('.mobile-header').style.display = 'flex';
    }

    // Update user info in sidebar
    const userName = document.querySelector('.user-info h4');
    if (userName && appData.user.name) {
        userName.textContent = appData.user.name;
    }

    checkDailyMoodPrompt();
    updateDashboard();
    checkReminders();
}

