            anxiety: selectedMoodValue <= 3 ? 7 : selectedMoodValue <= 6 ? 4 : 2,
            mood: Math.ceil(selectedMoodValue / 2),
            sleep: 7,
            dailyMood: selectedMoodValue
        };

        appData.mentalHealth = appData.mentalHealth.filter(m => m.date !== today);
        appData.mentalHealth.push(moodRecord);
        appData.settings.lastMoodCheck = today;

        saveData();
        updateMentalHealth();
        updateDashboard();

        modal.classList.remove('active');
        showNotification('Your mood has been recorded! 🌟');
    });
}

function createMoodParticles(moodValue, moodParticles, container) {
    // Clear existing particles
    container.innerHTML = '';

    const particles = moodParticles[moodValue] || ['✨'];
    const numParticles = Math.min(moodValue, 8);

    for (let i = 0; i < numParticles; i++) {
        setTimeout(() => {
            const particle = document.createElement('div');
            particle.className = 'particle';
            particle.textContent = particles[Math.floor(Math.random() * particles.length)];

            // Random position around the emoji
            const angle = (Math.PI * 2 / numParticles) * i;
            const radius = 60;
            const x = 50 + Math.cos(angle) * radius;
            const y = 50 + Math.sin(angle) * radius;

            particle.style.left = x + '%';
            particle.style.top = y + '%';

            container.appendChild(particle);

            setTimeout(() => particle.remove(), 2000);
        }, i * 100);
    }
}

// Settings
function setupSettings() {
    // Load settings
    document.getElementById('mood-reminder-toggle').checked = appData.settings.moodReminder;
    document.getElementById('mood-reminder-time').value = appData.settings.moodReminderTime;
    document.getElementById('task-reminder-toggle').checked = appData.settings.taskReminder;
    document.getElementById('reminder-hours').value = appData.settings.reminderHours;
    document.getElementById('animations-toggle').checked = appData.settings.animations;

    // Save settings on change
    document.getElementById('mood-reminder-toggle')?.addEventListener('change', function() {
        appData.settings.moodReminder = this.checked;
        saveData();
        showNotification('Mood reminder ' + (this.checked ? 'enabled' : 'disabled'));
    });

    document.getElementById('mood-reminder-time')?.addEventListener('change', function() {
        appData.settings.moodReminderTime = this.value;
        saveData();
        showNotification('Reminder time updated');
    });

    document.getElementById('task-reminder-toggle')?.addEventListener('change', function() {
        appData.settings.taskReminder = this.checked;
        saveData();
        showNotification('Task reminders ' + (this.checked ? 'enabled' : 'disabled'));
    });

    document.getElementById('reminder-hours')?.addEventListener('change', function() {
        appData.settings.reminderHours = parseInt(this.value);
        saveData();
        showNotification('Reminder time updated');
    });

    document.getElementById('animations-toggle')?.addEventListener('change', function() {
        appData.settings.animations = this.checked;
        document.body.style.setProperty('--animation-state', this.checked ? 'running' : 'paused');
        saveData();
        showNotification('Animations ' + (this.checked ? 'enabled' : 'disabled'));
    });

    // Export data
    document.getElementById('export-data-btn')?.addEventListener('click', () => {
        const dataStr = JSON.stringify(appData, null, 2);
        const dataBlob = new Blob([dataStr], {type: 'application/json'});
        const url = URL.createObjectURL(dataBlob);
        const link = document.createElement('a');
        link.href = url;
        link.download = 'swms-data-' + new Date().toISOString().split('T')[0] + '.json';
        link.click();
        showNotification('Data exported successfully!');
    });

    // Clear data
    document.getElementById('clear-data-btn')?.addEventListener('click', () => {
        if (confirm('Are you sure you want to clear all data? This cannot be undone.')) {
            localStorage.removeItem('swmsData');
            showNotification('All data cleared. Refreshing...');
            setTimeout(() => location.reload(), 1500);
        }
    });
}

// Reminders System
function checkReminders() {
    if (!appData.settings.taskReminder) return;

    const now = new Date();
    const reminderWindowMs = appData.settings.reminderHours * 60 * 60 * 1000;

    appData.tasks.forEach(task => {
        if (task.completed || task.reminded) return;

        const dueDate = new Date(task.dueDate + 'T23:59:59');
        const timeDiff = dueDate - now;

        if (timeDiff > 0 && timeDiff <= reminderWindowMs) {
            const hours = Math.ceil(timeDiff / (60 * 60 * 1000));
            showNotification(`⏰ Reminder: "${task.title}" is due in ${hours} hour${hours !== 1 ? 's' : ''}!`);
            task.reminded = true;
            saveData();
        }
    });
}

