function checkDailyMoodPrompt() {
    if (!appData.settings.moodReminder) return;

    const today = new Date().toISOString().split('T')[0];
    const lastCheck = appData.settings.lastMoodCheck;

    // Show mood check if not done today
    if (lastCheck !== today) {
        setTimeout(() => {
            document.getElementById('mood-check-modal').classList.add('active');
        }, 1000);
