function createStressChart() {
    const ctx = document.getElementById('stressChart');
    if (!ctx) return;

    if (window.stressChartInstance) {
        window.stressChartInstance.destroy();
    }

    const canvas = ctx;
    canvas.width = canvas.offsetWidth;
    canvas.height = 250;
    const context = canvas.getContext('2d');

    const last7Days = appData.mentalHealth.slice(-7);
    const labels = last7Days.map(d => {
        const date = new Date(d.date);
        return date.toLocaleDateString('en-US', { weekday: 'short' });
    });
    const stressData = last7Days.map(d => d.stress);

    const padding = 40;
    const width = canvas.width - padding * 2;
    const height = canvas.height - padding * 2;
    const pointSpacing = width / (stressData.length - 1);

    context.clearRect(0, 0, canvas.width, canvas.height);

    // Draw grid
    context.strokeStyle = '#475569';
    context.lineWidth = 1;
    for (let i = 0; i <= 10; i += 2) {
        const y = padding + (height / 10) * i;
        context.beginPath();
        context.moveTo(padding, y);
        context.lineTo(canvas.width - padding, y);
        context.stroke();

        context.fillStyle = '#94a3b8';
        context.font = '12px sans-serif';
        context.textAlign = 'right';
        context.fillText((10 - i).toString(), padding - 10, y + 4);
    }

    // Draw line with gradient
    const gradient = context.createLinearGradient(0, padding, 0, canvas.height - padding);
    gradient.addColorStop(0, '#ef4444');
    gradient.addColorStop(0.5, '#f59e0b');
    gradient.addColorStop(1, '#10b981');

    context.strokeStyle = gradient;
    context.lineWidth = 3;
    context.beginPath();

    stressData.forEach((stress, index) => {
        const x = padding + index * pointSpacing;
        const y = padding + height - (stress / 10) * height;

        if (index === 0) {
            context.moveTo(x, y);
        } else {
            context.lineTo(x, y);
        }

        // Draw point
        context.fillStyle = '#6366f1';
        context.beginPath();
        context.arc(x, y, 5, 0, Math.PI * 2);
        context.fill();

        // Draw label
        context.fillStyle = '#cbd5e1';
        context.font = '12px sans-serif';
        context.textAlign = 'center';
        context.fillText(labels[index], x, canvas.height - 10);
    });

    context.stroke();
}

function updateMoodHistory() {
    const container = document.getElementById('mood-history-list');

    if (appData.mentalHealth.length === 0) {
        container.innerHTML = '<p class="empty-state">No mood records yet</p>';
        return;
    }

    const moodEmojis = ['😢', '😟', '😐', '🙂', '😄'];
    const recent = [...appData.mentalHealth].reverse().slice(0, 10);

    container.innerHTML = recent.map(record => `
        <div class="mood-history-item">
            <div class="mood-emoji">${moodEmojis[record.mood - 1]}</div>
            <div class="mood-details">
                <p><strong>${formatDate(record.date)}</strong></p>
                <p>Stress: ${record.stress}/10 • Anxiety: ${record.anxiety}/10 • Sleep: ${record.sleep}h</p>
            </div>
        </div>
    `).join('');
}

// Mental Health Form
const stressSlider = document.getElementById('stress-slider');
const anxietySlider = document.getElementById('anxiety-slider');
const stressValue = document.getElementById('stress-value');
const anxietyValue = document.getElementById('anxiety-value');

if (stressSlider) {
    stressSlider.addEventListener('input', function() {
        stressValue.textContent = this.value;
    });
}

if (anxietySlider) {
