// Login/Signup Handlers
function setupLoginHandlers() {
    console.log('Setting up login handlers...');

    const loginForm = document.getElementById('login-form');
    const signupForm = document.getElementById('signup-form');
    const showSignupLink = document.getElementById('show-signup');
    const showLoginLink = document.getElementById('show-login');
    const loginContent = document.querySelector('.login-content');
    const signupContent = document.querySelector('.signup-content');

    console.log('Login form:', loginForm);
    console.log('Signup form:', signupForm);

    // Toggle between login and signup
    if (showSignupLink) {
        showSignupLink.addEventListener('click', (e) => {
            e.preventDefault();
            console.log('Switching to signup');
            loginContent.style.display = 'none';
            signupContent.style.display = 'block';
        });
    }

    if (showLoginLink) {
        showLoginLink.addEventListener('click', (e) => {
            e.preventDefault();
            console.log('Switching to login');
            signupContent.style.display = 'none';
            loginContent.style.display = 'block';
        });
    }

    // Handle login
    if (loginForm) {
        loginForm.addEventListener('submit', (e) => {
            e.preventDefault();
            console.log('LOGIN FORM SUBMITTED!');

            const emailField = document.getElementById('login-email');
            const passwordField = document.getElementById('login-password');

            const email = emailField ? emailField.value : '';
            const password = passwordField ? passwordField.value : '';

            console.log('Login attempt - Email:', email, 'Password:', password ? '***' : 'EMPTY');

            if (email && password) {
                appData.user.isLoggedIn = true;
                appData.user.email = email;
                appData.user.name = email.split('@')[0];
                saveData();

                console.log('Login successful - User:', appData.user.name);
                showMainApp();
                showNotification('Welcome! 🎉');
            } else {
                showNotification('Please fill in all fields');
            }
        });
    } else {
        console.log('ERROR: Login form not found!');
    }

    // Handle signup
    if (signupForm) {
        signupForm.addEventListener('submit', (e) => {
            e.preventDefault();
            console.log('SIGNUP FORM SUBMITTED!');

            const nameField = document.getElementById('signup-name');
            const emailField = document.getElementById('signup-email');
            const passwordField = document.getElementById('signup-password');
            const confirmField = document.getElementById('signup-confirm');

            const name = nameField ? nameField.value : '';
            const email = emailField ? emailField.value : '';
            const password = passwordField ? passwordField.value : '';
            const confirm = confirmField ? confirmField.value : '';

            console.log('Signup attempt - Name:', name, 'Email:', email, 'Password:', password ? '***' : 'EMPTY', 'Confirm:', confirm ? '***' : 'EMPTY');

            if (!password || !confirm) {
                showNotification('Please enter passwords');
                return;
            }

            if (password !== confirm) {
                showNotification('Passwords do not match!');
                return;
            }

            if (name && email && password) {
                appData.user.isLoggedIn = true;
                appData.user.name = name;
                appData.user.email = email;
                saveData();

                console.log('Signup successful - User:', name);
                showMainApp();
                showNotification('Account created! Welcome 🎉');
            } else {
                showNotification('Please fill in all fields');
            }
        });
    } else {
        console.log('ERROR: Signup form not found!');
    }
}

function showLoginPage() {
    console.log('Showing login page');
    const loginPage = document.getElementById('login-page');
    const appContainer = document.querySelector('.app-container');
    const mobileHeader = document.querySelector('.mobile-header');

    if (loginPage) loginPage.classList.add('active');
    if (appContainer) appContainer.style.display = 'none';
    if (mobileHeader) mobileHeader.style.display = 'none';
}

function showMainApp() {
    console.log('Showing main app');
    const loginPage = document.getElementById('login-page');
    const appContainer = document.querySelector('.app-container');
    const mobileHeader = document.querySelector('.mobile-header');

    if (loginPage) loginPage.classList.remove('active');
    if (appContainer) appContainer.style.display = 'flex';
    if (mobileHeader && window.innerWidth <= 768) mobileHeader.style.display = 'flex';

    // Update user info in sidebar
