input.content:
:root {
    --primary-color: #6bc4a6;
    --accent-color: #7d5a50;
    --bg-primary: #f8f6f3;
    --text-dark: #2c2c2c;
    --text-light: #6b6b6b;
    --border-color: #e8e4df;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    background: var(--bg-primary);
    color: var(--text-dark);
    line-height: 1.6;
}

/* Login Page */
.login-page {
    display: flex;
    min-height: 100vh;
    display: none;
}

.login-page.active {
    display: flex;
}

.login-container {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
}

.login-content, .signup-content {
    width: 100%;
    max-width: 400px;
}

.login-header {
    text-align: center;
    margin-bottom: 30px;
}

.login-logo {
    font-size: 48px;
    margin-bottom: 15px;
}

.login-header h1 {
    font-size: 28px;
    margin-bottom: 8px;
    color: var(--text-dark);
}

.login-header p {
    color: var(--text-light);
    font-size: 14px;
}

.login-form {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.form-group {
    display: flex;
    flex-direction: column;
}

.form-group label {
    font-size: 13px;
    font-weight: 600;
    margin-bottom: 6px;
    color: var(--text-dark);
}

.input-field {
    padding: 12px 14px;
    border: 1px solid var(--border-color);
    border-radius: 8px;
    font-size: 14px;
    transition: border-color 0.2s;
    font-family: inherit;
}

.input-field:focus {
    outline: none;
    border-color: var(--primary-color);
    box-shadow: 0 0 0 3px rgba(107, 196, 166, 0.1);
}

.btn {
    padding: 12px 20px;
    border: none;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s;
    font-family: inherit;
}

.btn-primary {
    background: var(--primary-color);
    color: white;
    width: 100%;
    margin-top: 8px;
}

.btn-primary:hover {
    background: #5ab895;
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(107, 196, 166, 0.3);
}

.login-footer {
    text-align: center;
    margin-top: 20px;
    font-size: 13px;
}

.login-footer a {
    color: var(--primary-color);
    text-decoration: none;
    font-weight: 600;
    cursor: pointer;
}

.login-illustration {
    flex: 1;
    background: linear-gradient(135deg, var(--primary-color) 0%, #5ab895 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    padding: 40px;
    text-align: center;
}

.illustration-content h2 {
    font-size: 32px;
    margin-bottom: 15px;
}

.illustration-content p {
    font-size: 16px;
    margin-bottom: 30px;
    opacity: 0.9;
}

.feature-list {
    display: flex;
    flex-direction: column;
    gap: 15px;
}

.feature-item {
    display: flex;
    align-items: center;
    gap: 12px;
    font-size: 14px;
}

.feature-icon {
    font-size: 24px;
}

/* App Container */
.app-container {
    display: none;
    grid-template-columns: 280px 1fr;
    min-height: 100vh;
    gap: 0;
}

.app-container.active {
    display: grid;
}

.sidebar {
    background: white;
    border-right: 1px solid var(--border-color);
    padding: 20px 0;
    overflow-y: auto;
}

.sidebar-header {
    padding: 0 20px 20px;
    border-bottom: 1px solid var(--border-color);
    margin-bottom: 20px;
}

.sidebar-header h2 {
    font-size: 20px;
    margin-bottom: 5px;
}

.sidebar-header p {
    font-size: 12px;
    color: var(--text-light);
}

.nav-item {
    padding: 12px 20px;
    cursor: pointer;
    transition: all 0.2s;
    font-size: 14px;
    color: var(--text-light);
    display: flex;
    align-items: center;
    gap: 10px;
}

.nav-item:hover {
    background: var(--bg-primary);
    color: var(--text-dark);
}

.nav-item.active {
    background: var(--primary-color);
    color: white;
    border-left: 4px solid var(--accent-color);
}

.main-content {
    padding: 30px;
    overflow-y: auto;
    display: grid;
    grid-template-columns: 1fr;
}

.view-section {
    display: none;
    animation: fadeIn 0.3s;
}

.view-section.active {
    display: block;
}

@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

.dashboard-header {
    margin-bottom: 30px;
}

.dashboard-header h1 {
    font-size: 32px;
    margin-bottom: 8px;
}

.dashboard-header p {
    color: var(--text-light);
    font-size: 14px;
}

.stats-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 30px;
}

.stat-card {
    background: white;
    padding: 20px;
    border-radius: 10px;
    border: 1px solid var(--border-color);
    text-align: center;
}

.stat-value {
    font-size: 32px;
    font-weight: 700;
    color: var(--primary-color);
    margin-bottom: 8px;
}

.stat-label {
    font-size: 13px;
    color: var(--text-light);
}

.dashboard-section {
    background: white;
    padding: 20px;
    border-radius: 10px;
    border: 1px solid var(--border-color);
    margin-bottom: 20px;
}

.dashboard-section h2 {
    font-size: 18px;
    margin-bottom: 15px;
}

.task-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.task-item {
    padding: 12px 15px;
    background: var(--bg-primary);
    border-left: 4px solid var(--primary-color);
    border-radius: 6px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 14px;
}

.task-item.completed {
    opacity: 0.6;
    text-decoration: line-through;
}

.task-item.priority-high {
    border-left-color: #ff6b6b;
}

.task-item.priority-medium {
    border-left-color: var(--accent-color);
}

.task-item.priority-low {
    border-left-color: #4ecdc4;
}

.grades-list {
    display: flex;
    flex-direction: column;
    gap: 12px;
    margin-bottom: 20px;
}

.grade-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 15px;
    background: white;
    border-radius: 8px;
    border: 1px solid var(--border-color);
}

.grade-value {
    font-size: 24px;
    font-weight: 700;
    color: var(--primary-color);
}

.mood-display {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 15px;
    margin-bottom: 20px;
}

.mood-stat {
    padding: 15px;
    background: white;
    border-radius: 8px;
    border: 1px solid var(--border-color);
    text-align: center;
}

.mood-stat strong {
    display: block;
    font-size: 24px;
    color: var(--primary-color);
    margin-top: 5px;
}

/* Mood Check Modal */
.mood-check-modal {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.mood-check-modal.active {
    display: flex;
}

.mood-check-content {
    background: white;
    padding: 30px;
    border-radius: 16px;
    max-width: 500px;
    width: 90%;
}

.mood-check-header {
    text-align: center;
    margin-bottom: 25px;
}

.mood-check-header h2 {
    font-size: 24px;
    margin-bottom: 8px;
}

.mood-check-header p {
    color: var(--text-light);
    font-size: 14px;
}

.mood-scale-numbers {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 10px;
}

.mood-number {
    padding: 12px;
    border: 2px solid var(--border-color);
    background: white;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
}

.mood-number:hover {
    border-color: var(--primary-color);
    color: var(--primary-color);
}

.mood-number.selected {
    background: var(--primary-color);
    color: white;
    border-color: var(--primary-color);
}

/* Notification */
.notification {
    position: fixed;
    bottom: 20px;
    right: 20px;
    background: var(--primary-color);
    color: white;
    padding: 15px 20px;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 600;
    animation: slideIn 0.3s ease-out;
    z-index: 2000;
}

@keyframes slideIn {
    from {
        transform: translateX(400px);
        opacity: 0;
    }
    to {
        transform: translateX(0);
        opacity: 1;
    }
}

/* Mobile */
@media (max-width: 768px) {
    .login-page {
        flex-direction: column;
    }

    .login-illustration {
        display: none;
    }

    .login-container {
        padding: 15px;
    }

    .app-container {
        grid-template-columns: 1fr;
    }

    .sidebar {
        display: none;
        position: fixed;
        left: 0;
        top: 0;
        width: 250px;
        height: 100vh;
        z-index: 100;
        border-right: none;
    }

    .sidebar.open {
        display: block;
    }

    .main-content {
        padding: 15px;
    }

    .stats-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 12px;
    }

    .stat-value {
        font-size: 24px;
    }

    .mood-scale-numbers {
        grid-template-columns: repeat(5, 1fr);
    }
}

