    display: flex;
    flex-direction: column;
    gap: 12px;
    margin-bottom: 20px;
}

.grade-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 15px;
    background: white;
    border-radius: 8px;
    border: 1px solid var(--border-color);
}

.grade-value {
    font-size: 24px;
    font-weight: 700;
    color: var(--primary-color);
}

.mood-display {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 15px;
    margin-bottom: 20px;
}

.mood-stat {
    padding: 15px;
    background: white;
    border-radius: 8px;
    border: 1px solid var(--border-color);
    text-align: center;
}

.mood-stat strong {
    display: block;
    font-size: 24px;
    color: var(--primary-color);
    margin-top: 5px;
}

/* Mood Check Modal */
.mood-check-modal {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.mood-check-modal.active {
    display: flex;
}

.mood-check-content {
    background: white;
    padding: 30px;
    border-radius: 16px;
    max-width: 500px;
    width: 90%;
}

.mood-check-header {
    text-align: center;
    margin-bottom: 25px;
}

.mood-check-header h2 {
    font-size: 24px;
    margin-bottom: 8px;
}

.mood-check-header p {
    color: var(--text-light);
    font-size: 14px;
}

.mood-scale-numbers {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 10px;
}

.mood-number {
    padding: 12px;
    border: 2px solid var(--border-color);
    background: white;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
}

.mood-number:hover {
    border-color: var(--primary-color);
    color: var(--primary-color);
}

.mood-number.selected {
    background: var(--primary-color);
    color: white;
    border-color: var(--primary-color);
}

/* Notification */
.notification {
    position: fixed;
    bottom: 20px;
    right: 20px;
    background: var(--primary-color);
    color: white;
    padding: 15px 20px;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 600;
    animation: slideIn 0.3s ease-out;
    z-index: 2000;
}

@keyframes slideIn {
    from {
        transform: translateX(400px);
        opacity: 0;
    }
    to {
        transform: translateX(0);
        opacity: 1;
    }
}

/* Mobile */
@media (max-width: 768px) {
    .login-page {
        flex-direction: column;
    }

    .login-illustration {
        display: none;
    }

    .login-container {
        padding: 15px;
    }

    .app-container {
        grid-template-columns: 1fr;
    }

    .sidebar {
        display: none;
        position: fixed;
        left: 0;
        top: 0;
        width: 250px;
        height: 100vh;
        z-index: 100;
        border-right: none;
    }

    .sidebar.open {
        display: block;
    }

    .main-content {
        padding: 15px;
    }

    .stats-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 12px;
    }

    .stat-value {
        font-size: 24px;
    }

    .mood-scale-numbers {
        grid-template-columns: repeat(5, 1fr);
    }
}

