150	    const completionRate = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;
151	    const avgGrade = appData.grades.length > 0 ? (appData.grades.reduce((s, g) => s + g.grade, 0) / appData.grades.length).toFixed(2) : 0;
152	
153	    dashboard.innerHTML = `
154	        <div class="dashboard-header">
155	            <h1>Welcome, ${appData.user.name}! 👋</h1>
