161	                <div class="stat-label">Total Tasks</div>
162	            </div>
163	            <div class="stat-card">
164	                <div class="stat-value">${completionRate}%</div>
165	                <div class="stat-label">Completion</div>
166	            </div>
167	            <div class="stat-card">
168	                <div class="stat-value">${avgGrade}</div>
169	                <div class="stat-label">Avg Grade</div>
170	            </div>
